"""Base interface definitions."""

import abc
import typing

from . import _utils
from ._compat import contextlib

__all__ = export = _utils.ExportList()

T = typing.TypeVar('T')


@export
class IDictable(typing.Generic[T]):
    """Requires implementing classes to define :meth:`to_dict` method."""

    @abc.abstractmethod
    def to_dict(self) -> dict:
        """Convert this object to dict."""


@export
class IClosable(contextlib.AbstractAsyncContextManager):
    """An interface for closable objects."""

    async def __aexit__(self, exc_type, exc, tb):
        if not self.is_closed():
            await self.close()

    @abc.abstractmethod
    def is_closed(self) -> bool:
        """Check if this object is closed or during closing."""

    @abc.abstractmethod
    async def close(self):
        """Close this object.

        Just after this method starts executing, :meth:`is_closed` should
        return True. Calling this method more than once for same object is
        safe.
        """
